<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { anularLectura, generarPadron, listarPadron, urlImpresionRuta, type LecturaPadron, type NodoAvance, type Option } from '../services/padronLecturas'

const distritos=ref<NodoAvance[]>([]),sectores=ref<NodoAvance[]>([]),rutas=ref<NodoAvance[]>([]),rows=ref<LecturaPadron[]>([]),calles=ref<Option[]>([]),loading=ref(false),generating=ref(false),error=ref(''),success=ref(''),total=ref(0),lastPage=ref(1)
const filters=reactive({distrito_id:'',sector_id:'',ruta_id:'',calle_id:'',criterio:'',estado:'',page:1})
const stage=computed(()=>filters.ruta_id?'lecturas':filters.sector_id?'rutas':filters.distrito_id?'sectores':'distritos')
const selectedDistrict=computed(()=>distritos.value.find(x=>x.id===Number(filters.distrito_id)))
const selectedSector=computed(()=>sectores.value.find(x=>x.id===Number(filters.sector_id)))
const selectedRoute=computed(()=>rutas.value.find(x=>x.id===Number(filters.ruta_id)))
const percentage=(x:NodoAvance)=>x.total?Math.round(x.leidos*100/x.total):0
async function load(page=1){loading.value=true;error.value='';filters.page=page;try{const r=await listarPadron(filters);distritos.value=r.distritos;sectores.value=r.sectores;rutas.value=r.rutas;rows.value=r.lecturas;calles.value=r.calles;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=msg(e)}finally{loading.value=false}}
function chooseDistrict(id:number){filters.distrito_id=String(id);filters.sector_id='';filters.ruta_id='';load(1)}
function chooseSector(id:number){filters.sector_id=String(id);filters.ruta_id='';load(1)}
function chooseRoute(id:number){filters.ruta_id=String(id);load(1)}
function back(){if(filters.ruta_id)filters.ruta_id='';else if(filters.sector_id)filters.sector_id='';else filters.distrito_id='';load(1)}
async function generate(x:NodoAvance){if(x.generado){error.value='El padrón de este sector ya fue generado.';return}if(!confirm(`¿Generar los padrones de lectura del sector ${x.nombre}?`))return;generating.value=true;error.value='';try{const r=await generarPadron(x.id);success.value=`Padrón generado correctamente: ${r.generados} medidores incorporados.`;await load(1)}catch(e){error.value=msg(e)}finally{generating.value=false}}
async function remove(x:LecturaPadron){if(!confirm(`¿Anular la lectura registrada del medidor ${x.medidor}?`))return;error.value='';try{await anularLectura(x.id);success.value='Lectura anulada correctamente.';await load(filters.page)}catch(e){error.value=msg(e)}}
function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Padrón de lecturas</nav><header class="hero"><div class="mark">PL</div><div><small>EVAN · MEDICIÓN</small><h1>Padrón de lecturas</h1><p>Generación y recorrido operativo de medidores por distrito, sector y ruta.</p></div><div v-if="stage!=='distritos'" class="crumb"><span v-if="selectedDistrict">{{selectedDistrict.nombre}}</span><span v-if="selectedSector">› {{selectedSector.nombre}}</span><span v-if="selectedRoute">› {{selectedRoute.nombre}}</span></div><button v-if="stage!=='distritos'" @click="back">← Volver</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p>
<section v-if="stage==='lecturas'" class="filters"><label>Medidor o enganche<input v-model.trim="filters.criterio" placeholder="Número de medidor" @keyup.enter="load(1)"></label><label>Calle<select v-model="filters.calle_id"><option value="">Todas</option><option v-for="x in calles" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option value="pendiente">Pendientes</option><option value="registrado">Registrados</option></select></label><button @click="load(1)">Buscar</button><a v-if="selectedRoute" :href="urlImpresionRuta(selectedRoute.id)" target="_blank">Imprimir padrón</a></section>
<div v-if="loading" class="empty">Cargando padrón…</div><template v-else><section v-if="stage==='distritos'||stage==='sectores'||stage==='rutas'" class="nodes"><article v-for="x in stage==='distritos'?distritos:stage==='sectores'?sectores:rutas" :key="x.id"><header><small>{{stage==='distritos'?'DISTRITO':stage==='sectores'?'SECTOR':'RUTA DE LECTURA'}}</small><em>{{percentage(x)}}%</em></header><h2>{{x.nombre}}</h2><strong>{{x.leidos}} <span>/ {{x.total}} lecturas</span></strong><i><b :style="{width:percentage(x)+'%'}"></b></i><footer><button v-if="stage==='distritos'" @click="chooseDistrict(x.id)">Ver sectores</button><template v-else-if="stage==='sectores'"><button @click="chooseSector(x.id)">Ver rutas</button><button class="generate" :disabled="generating||x.generado" @click="generate(x)">{{x.generado?'Padrón generado':'Generar padrón'}}</button></template><template v-else><button @click="chooseRoute(x.id)">Ver medidores</button><a :href="urlImpresionRuta(x.id)" target="_blank">PDF</a></template></footer></article></section><div v-else-if="!rows.length" class="empty">No existen medidores en esta selección.</div><section v-else class="meters"><article v-for="x in rows" :key="x.id" :class="{done:x.registrado}"><header><span>Sec. {{x.secuencia}}</span><em>{{x.registrado?'Lectura registrada':'Pendiente'}}</em></header><img v-if="x.fotografia" :src="x.fotografia" alt="Predio"><h2>{{x.cliente}}</h2><p>{{x.direccion}}</p><dl><div><dt>Medidor</dt><dd>{{x.medidor}}</dd></div><div><dt>Suministro</dt><dd>{{x.suministro}}</dd></div><div><dt>Código catastral</dt><dd>{{x.codigo_catastral}}</dd></div><div><dt>Categoría</dt><dd>{{x.categoria}}</dd></div><div><dt>Lectura anterior</dt><dd>{{x.lectura_anterior??'—'}}</dd></div><div><dt>Lectura actual</dt><dd>{{x.lectura_actual??'—'}}</dd></div></dl><footer><RouterLink :to="{name:'comercial-medicion-lecturas',query:{lectura:x.id}}">{{x.registrado?'Ver lectura':'Registrar lectura'}}</RouterLink><button v-if="x.registrado" @click="remove(x)">Anular</button></footer></article></section></template><footer v-if="stage==='lecturas'&&lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}} · {{total}} medidores</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer></div></template>

<style scoped>
.page{--a:#228263;color:#34464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.nodes small{color:var(--a);font-size:.53rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.hero>button,.filters button,.nodes button,.pages button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem}.crumb{margin-left:auto;color:#69777e;font-size:.5rem}.flash{padding:10px;font-size:.6rem}.good{color:#257359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d8e1e4;border-radius:5px;font:inherit;font-size:.52rem}.filters a,.nodes a{padding:8px 11px;border-radius:6px;color:#fff;background:#637984;text-decoration:none;font-size:.5rem}.nodes{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.nodes article{padding:16px;border-radius:9px;background:#fff}.nodes header{display:flex;justify-content:space-between}.nodes em{color:var(--a);font-size:.54rem;font-style:normal}.nodes h2{margin:11px 0 2px;font-size:.75rem}.nodes strong{font-size:1rem}.nodes strong span{color:#819097;font-size:.48rem;font-weight:400}.nodes i{height:6px;margin:10px 0;display:block;overflow:hidden;background:#e4ebe8}.nodes i b{height:100%;display:block;background:var(--a)}.nodes footer{display:flex;gap:6px}.nodes .generate{background:#c07b2e}.nodes button:disabled{opacity:.55}.meters{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.meters article{padding:13px;border-top:3px solid #d58a38;border-radius:8px;background:#fff}.meters article.done{border-color:var(--a)}.meters header{display:flex;justify-content:space-between;font-size:.46rem}.meters em{color:var(--a);font-style:normal}.meters img{width:100%;height:115px;margin-top:8px;object-fit:cover}.meters h2{margin:9px 0 2px;font-size:.65rem}.meters p{min-height:30px;color:#76848a;font-size:.48rem}.meters dl{display:grid;grid-template-columns:1fr 1fr;gap:6px}.meters dt{color:#89969b;font-size:.41rem}.meters dd{margin:2px 0;font-size:.48rem;font-weight:700}.meters footer{display:flex;gap:5px}.meters footer a,.meters footer button{flex:1;padding:7px;border:0;border-radius:5px;color:#fff;background:var(--a);text-align:center;text-decoration:none;font-size:.47rem}.meters footer button{background:#a8494b}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.5rem}@media(max-width:850px){.nodes,.meters{grid-template-columns:1fr 1fr}.filters{flex-wrap:wrap}.filters label{min-width:28%}}@media(max-width:550px){.hero{flex-wrap:wrap}.crumb{margin-left:0;width:100%}.nodes,.meters{grid-template-columns:1fr}.filters{align-items:stretch;flex-direction:column}.filters label{width:100%}}
</style>
